MODEL_SOURCE = 'from __future__ import annotations\n\nimport torch\nfrom torch import nn\nfrom torchvision.models import ResNet18_Weights, resnet18\n\n\nclass LanguageConditionedVLA(nn.Module):\n    """Dual-camera language-conditioned action policy."""\n\n    def __init__(\n        self,\n        state_dim: int = 10,\n        action_dim: int = 7,\n        vocab_size: int = 4096,\n        language_dim: int = 64, pretrained_vision: bool = False,\n    ) -> None:\n        super().__init__()\n\n        if action_dim != 7:\n            raise ValueError(\n                "This model expects 7D IK-Rel actions"\n            )\n\n        vision = resnet18(weights=ResNet18_Weights.DEFAULT if pretrained_vision else None)\n        vision.fc = nn.Identity()\n        self.vision = vision\n\n        self.state_encoder = nn.Sequential(\n            nn.Linear(state_dim, 64),\n            nn.LayerNorm(64),\n            nn.GELU(),\n            nn.Linear(64, 64),\n            nn.GELU(),\n        )\n\n        self.token_embedding = nn.Embedding(\n            vocab_size,\n            language_dim,\n            padding_idx=0,\n        )\n\n        self.language_encoder = nn.GRU(\n            input_size=language_dim,\n            hidden_size=language_dim,\n            batch_first=True,\n        )\n\n        fusion_dim = (\n            512\n            + 512\n            + 64\n            + language_dim\n        )\n\n        self.fusion = nn.Sequential(\n            nn.Linear(fusion_dim, 512),\n            nn.LayerNorm(512),\n            nn.GELU(),\n            nn.Dropout(0.1),\n            nn.Linear(512, 256),\n            nn.LayerNorm(256),\n            nn.GELU(),\n        )\n\n        self.arm_head = nn.Linear(256, 6)\n        self.gripper_head = nn.Linear(256, 1)\n\n    def set_instruction(self, instruction):\n        if instruction not in (\'pick up the red cube\', \'pick up the blue cube\'):\n            raise ValueError(\'Only red/blue cube instructions are supported\')\n\n    def encode_language(\n        self,\n        language: torch.Tensor,\n    ) -> torch.Tensor:\n        embedded = self.token_embedding(language)\n\n        lengths = (language != 0).sum(dim=1).clamp_min(1).cpu()\n        packed = nn.utils.rnn.pack_padded_sequence(\n            embedded, lengths, batch_first=True, enforce_sorted=False\n        )\n        _, hidden = self.language_encoder(packed)\n\n        return hidden[-1]\n\n    def forward(\n        self,\n        table_image: torch.Tensor,\n        wrist_image: torch.Tensor,\n        state: torch.Tensor,\n        language: torch.Tensor,\n    ) -> dict[str, torch.Tensor]:\n        batch_size = table_image.shape[0]\n\n        combined_images = torch.cat(\n            [table_image, wrist_image],\n            dim=0,\n        )\n\n        combined_features = self.vision(\n            combined_images\n        )\n\n        table_feature = combined_features[\n            :batch_size\n        ]\n        wrist_feature = combined_features[\n            batch_size:\n        ]\n\n        state_feature = self.state_encoder(\n            state\n        )\n        language_feature = self.encode_language(\n            language\n        )\n\n        fused = torch.cat(\n            [\n                table_feature,\n                wrist_feature,\n                state_feature,\n                language_feature,\n            ],\n            dim=-1,\n        )\n\n        feature = self.fusion(fused)\n\n        arm_action = torch.tanh(\n            self.arm_head(feature)\n        )\n        gripper_logit = self.gripper_head(\n            feature\n        ).squeeze(-1)\n\n        return {\n            "arm_action": arm_action,\n            "gripper_logit": gripper_logit,\n            "language_feature": language_feature,\n        }\n\n    @staticmethod\n    def build_action(\n        output: dict[str, torch.Tensor],\n    ) -> torch.Tensor:\n        closed = (\n            torch.sigmoid(\n                output["gripper_logit"]\n            )\n            >= 0.5\n        )\n\n        gripper_action = torch.where(\n            closed,\n            torch.full_like(\n                output["gripper_logit"],\n                -1.0,\n            ),\n            torch.full_like(\n                output["gripper_logit"],\n                1.0,\n            ),\n        ).unsqueeze(-1)\n\n        return torch.cat(\n            [\n                output["arm_action"],\n                gripper_action,\n            ],\n            dim=-1,\n        )\n'
TEMPORAL_SOURCE = 'import torch\nfrom torch import nn\n\nclass TemporalAction(nn.Module):\n    """Causal recurrent action decoder; no teacher phase or step input."""\n    def __init__(self):\n        super().__init__()\n        self.project = nn.Sequential(nn.Linear(256, 128), nn.LayerNorm(128), nn.GELU())\n        self.memory = nn.GRU(128, 128, batch_first=True)\n        self.output = nn.Linear(128, 7)\n        self.register_buffer(\'feature_mean\', torch.zeros(256))\n        self.register_buffer(\'feature_scale\', torch.ones(256))\n        self.register_buffer(\'action_mean\', torch.zeros(6))\n        self.register_buffer(\'action_scale\', torch.ones(6))\n\n    def forward(self, features, hidden=None):\n        x = self.project((features-self.feature_mean)/self.feature_scale)\n        x, hidden = self.memory(x, hidden)\n        y = self.output(x)\n        arm = (y[..., :6]*self.action_scale+self.action_mean).clamp(-1, 1)\n        return arm, y[..., 6], hidden\n'
WORKER_SOURCE = '"""Offline color-conditioned recurrent behavioral cloning; no simulator inputs."""\nfrom pathlib import Path\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport time\n\ndef require(condition, message):\n    if not condition:\n        raise RuntimeError(message)\n\ndef file_sha(path):\n    h = hashlib.sha256()\n    with Path(path).open(\'rb\') as f:\n        for block in iter(lambda: f.read(1024 * 1024), b\'\'):\n            h.update(block)\n    return h.hexdigest()\n\ndef split_standard_records(records):\n    identities = [(r[\'dx_mm\'], r[\'dy_mm\'], r[\'layout\'], r[\'instruction\']) for r in records]\n    expected = {(dx, dy, layout, \'pick up the \' + color + \' cube\')\n                for dx, dy in ((0, 0), (-10, 0), (10, 0), (0, -10), (0, 10), (10, 10), (-10, 10), (10, -10))\n                for layout in (\'red_yminus_blue_yplus\', \'blue_yminus_red_yplus\')\n                for color in (\'red\', \'blue\')}\n    expected.update({(-20, -20, \'red_yminus_blue_yplus\', \'pick up the blue cube\'), (-20, 20, \'red_yminus_blue_yplus\', \'pick up the red cube\'), (-20, 20, \'blue_yminus_red_yplus\', \'pick up the red cube\'), (-20, 20, \'blue_yminus_red_yplus\', \'pick up the blue cube\'), (20, 20, \'blue_yminus_red_yplus\', \'pick up the red cube\'), (0, 20, \'red_yminus_blue_yplus\', \'pick up the blue cube\'), (20, -20, \'red_yminus_blue_yplus\', \'pick up the blue cube\'), (-20, -20, \'red_yminus_blue_yplus\', \'pick up the red cube\'), (20, 20, \'red_yminus_blue_yplus\', \'pick up the blue cube\'), (0, 20, \'red_yminus_blue_yplus\', \'pick up the red cube\'), (0, 20, \'blue_yminus_red_yplus\', \'pick up the blue cube\'), (-20, -20, \'blue_yminus_red_yplus\', \'pick up the blue cube\'), (0, 20, \'blue_yminus_red_yplus\', \'pick up the red cube\'), (20, 20, \'red_yminus_blue_yplus\', \'pick up the red cube\'), (-20, 20, \'red_yminus_blue_yplus\', \'pick up the blue cube\'), (20, 20, \'blue_yminus_red_yplus\', \'pick up the blue cube\')})\n    expected.add((20,-20,\'red_yminus_blue_yplus\',\'pick up the red cube\'))\n    require(len(identities) == 49 and set(identities) == expected, \'Incomplete or duplicate audited trials\')\n    train = [r for r in records if (r[\'dx_mm\'], r[\'dy_mm\']) != (0, 10)]\n    valid = [r for r in records if (r[\'dx_mm\'], r[\'dy_mm\']) == (0, 10)]\n    require(len(train) == 45 and len(valid) == 4, \'Unexpected split\')\n    return train, valid\n\ndef split_records(records):\n    standard=[r for r in records if r.get(\'episode_role\')==\'standard\']\n    recovery=[r for r in records if r.get(\'episode_role\')==\'recovery\']\n    train,valid=split_standard_records(standard)\n    require(len(records)==50 and len(recovery)==1,\'Expected 49 standard and one recovery episode\')\n    r=recovery[0]\n    require((r[\'dx_mm\'],r[\'dy_mm\'],r[\'layout\'],r[\'instruction\'])==(20,-20,\'red_yminus_blue_yplus\',\'pick up the red cube\'),\'Unexpected recovery condition\')\n    require(r.get(\'context_samples\')==500 and r.get(\'context_actions_are_labels\') is False,\'Invalid recovery context contract\')\n    require(len({r[\'dataset\'] for r in records})==50,\'Duplicate dataset paths\')\n    return train+recovery,valid\n\n\ndef sequence_chunks(length, window):\n    require(length > 0 and window > 0, \'Invalid sequence/window size\')\n    return [(start, min(length, start + window)) for start in range(0, length, window)]\n\ndef language_tokens(text):\n    require(text in (\'pick up the red cube\', \'pick up the blue cube\'), \'Unsupported instruction\')\n    return [1 + int.from_bytes(hashlib.blake2b(word.encode(), digest_size=4).digest(), \'little\') % 4095\n            for word in text.lower().split()]\n\ndef atomic_json(path, value):\n    temporary = path.with_suffix(path.suffix + \'.tmp\')\n    with temporary.open(\'w\', encoding=\'utf-8\') as f:\n        json.dump(value, f, ensure_ascii=False, indent=2)\n        f.flush()\n        os.fsync(f.fileno())\n    temporary.replace(path)\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--manifest\', type=Path, required=True)\n    parser.add_argument(\'--output-dir\', type=Path, required=True)\n    parser.add_argument(\'--epochs\', type=int, default=300)\n    parser.add_argument(\'--patience\', type=int, default=40)\n    parser.add_argument(\'--window\', type=int, default=128)\n    parser.add_argument(\'--image-batch\', type=int, default=32)\n    args = parser.parse_args()\n    require(args.epochs > 0 and args.patience > 0 and args.window > 0 and args.image_batch > 0, \'Invalid options\')\n    import h5py\n    import numpy as np\n    import torch\n    from torch.nn import functional as F\n    from color_model import LanguageConditionedVLA\n    from color_temporal import TemporalAction\n    require(torch.cuda.is_available(), \'CUDA unavailable; training not started\')\n    device = torch.device(\'cuda:0\')\n    torch.set_num_threads(8)\n    random.seed(2058)\n    np.random.seed(2058)\n    torch.manual_seed(2058)\n    torch.cuda.manual_seed_all(2058)\n    torch.backends.cudnn.benchmark = False\n    torch.backends.cudnn.deterministic = True\n    started = time.monotonic()\n    out = args.output_dir\n    manifest = json.loads(args.manifest.read_text())\n    require(manifest.get(\'schema\') == \'color_recovery_training_manifest_v1\', \'Unexpected manifest format\')\n    audit = json.loads((args.manifest.parent / \'audit_results.json\').read_text())\n    require(audit.get(\'passed\') is True and audit[\'total_episodes\'] == 50, \'Audit did not pass\')\n    train_records, valid_records = split_records(manifest[\'episodes\'])\n    baseline_path = Path(\'/workspace/step4/vla_interior_gripper29_fit_gx7ippj0/candidate.pt\')\n    baseline_sha = file_sha(baseline_path)\n    require(baseline_sha == \'2cac0faa70e70ca69ad13553ef816aa8f2410213bc73f839cc9d0e3b441dace9\', \'Adopted checkpoint changed\')\n    baseline = torch.load(baseline_path, map_location=\'cpu\', weights_only=True)\n    require(baseline[\'format\'] == \'pick_temporal_action_v1\', \'Unexpected baseline format\')\n    parent = baseline[\'parent_checkpoint\']\n    config = {k: int(parent[k]) for k in (\'state_dim\', \'action_dim\', \'vocab_size\', \'language_dim\')}\n    require(config[\'state_dim\'] == 9 and config[\'action_dim\'] == 7, \'Unexpected state/action dimensions\')\n    model = LanguageConditionedVLA(**config).to(device)\n    model.load_state_dict(parent[\'model\'], strict=True)\n    decoder = TemporalAction().to(device)\n    decoder.load_state_dict(baseline[\'temporal_state\'], strict=True)\n    del parent, baseline\n    warm_path=Path(\'/workspace/step5/color_train_range20_6c624z6h/best.pt\')\n    warm_sha=file_sha(warm_path)\n    require(warm_sha==\'87a7b8759e3e61e41bdb6863d166adf2479b377b613cc64b98e51bc573213259\',\'Previous recovery checkpoint changed\')\n    warm=torch.load(warm_path,map_location=\'cpu\',weights_only=True)\n    require(warm[\'format\']==\'color_temporal_action_v1\' and warm[\'config\']==config,\'Warm-start configuration mismatch\')\n    model.load_state_dict(warm[\'model\'],strict=True)\n    decoder.load_state_dict(warm[\'temporal_state\'],strict=True)\n    del warm\n    for module in (model.vision, model.arm_head, model.gripper_head):\n        for parameter in module.parameters():\n            parameter.requires_grad_(False)\n    model.vision.eval()\n    mean = torch.tensor([.485, .456, .406], device=device)[None, :, None, None]\n    std = torch.tensor([.229, .224, .225], device=device)[None, :, None, None]\n    cache = []\n    for number, record in enumerate(manifest[\'episodes\'], 1):\n        path = Path(record[\'dataset\'])\n        require(file_sha(path) == record[\'sha256\'], \'Audited dataset changed: \' + str(path))\n        with h5py.File(path, \'r\') as f:\n            demo = f[\'data/demo_0\']\n            obs = demo[\'obs\']\n            n = record[\'samples\']\n            require(len(demo[\'actions\']) == n and bool(f.attrs[\'training_eligible\']), \'Invalid episode\')\n            require(str(demo.attrs[\'language_instruction\']) == record[\'instruction\'], \'Instruction changed\')\n            require(float(f.attrs[\'action_scale\']) == .5 and abs(float(f.attrs[\'step_dt\']) - .02) < 1e-8, \'Unsupported action scale/time step\')\n            require(np.array_equal(demo[\'language_tokens\'][()], language_tokens(record[\'instruction\'])), \'Token mismatch\')\n            context_len=500 if record.get(\'episode_role\')==\'recovery\' else 0\n            if context_len:\n                require(f.attrs[\'schema\']==\'color_recovery_teacher_v1\' and not bool(f.attrs[\'context_is_teacher\']),\'Invalid context provenance\')\n                context=f[\'recovery_context/obs\']\n                require(all(len(context[k])==500 for k in (\'table_cam\',\'wrist_cam\',\'eef_pos\',\'eef_quat\',\'gripper_pos\')),\'Context length mismatch\')\n                obs={k:np.concatenate([context[k][()],obs[k][()]],axis=0) for k in (\'table_cam\',\'wrist_cam\',\'eef_pos\',\'eef_quat\',\'gripper_pos\')}\n            encoded_n=n+context_len\n            features = []\n            for start in range(0, encoded_n, args.image_batch):\n                stop = min(encoded_n, start + args.image_batch)\n                images = [torch.as_tensor(obs[cam][start:stop], device=device).permute(0, 3, 1, 2).float() / 255.\n                          for cam in (\'table_cam\', \'wrist_cam\')]\n                require(all(tuple(im.shape[1:]) == (3, 200, 200) for im in images), \'Unexpected RGB resolution\')\n                with torch.no_grad():\n                    encoded = model.vision((torch.cat(images) - mean) / std)\n                    b = stop - start\n                    features.append(torch.cat((encoded[:b], encoded[b:]), dim=1).cpu())\n            state = np.concatenate([obs[k][()] for k in (\'eef_pos\', \'eef_quat\', \'gripper_pos\')], axis=1).astype(np.float32)\n            require(state.shape == (encoded_n, 9) and np.isfinite(state).all(), \'Invalid state array\')\n            row = dict(record=record, context_len=context_len, vision=torch.cat(features), state=torch.from_numpy(state),\n                       language=torch.tensor(language_tokens(record[\'instruction\']), dtype=torch.long),\n                       actions=torch.from_numpy(demo[\'actions\'][()].astype(np.float32)))\n            require(torch.isfinite(row[\'vision\']).all().item(), \'Nonfinite vision features\')\n            cache.append(row)\n        print(\'FEATURE_CACHE_PROGRESS\', json.dumps(dict(episode=number, total=50, samples=n, elapsed_seconds=round(time.monotonic()-started, 1))), flush=True)\n    train_ids = {r[\'dataset\'] for r in train_records}\n    train = [r for r in cache if r[\'record\'][\'dataset\'] in train_ids]\n    valid = [r for r in cache if r[\'record\'][\'dataset\'] not in train_ids]\n    all_targets = torch.cat([r[\'actions\'] for r in train])\n    label_scale = all_targets[:, :6].std(dim=0).clamp_min(.005).to(device)\n    closed = (all_targets[:, 6] < 0).sum().item()\n    pos_weight = torch.tensor((len(all_targets)-closed)/max(closed, 1), device=device)\n    parameters = [p for p in list(model.parameters()) + list(decoder.parameters()) if p.requires_grad]\n    optimizer = torch.optim.AdamW(parameters, lr=1e-5, weight_decay=1e-4)\n\n    def predict(row, start, stop, hidden):\n        offset=row.get("context_len",0)\n        start,stop=start+offset,stop+offset\n        visual = row[\'vision\'][start:stop].to(device)\n        state = row[\'state\'][start:stop].to(device)\n        language = row[\'language\'].to(device)[None]\n        encoded_language = model.encode_language(language).expand(stop-start, -1)\n        features = model.fusion(torch.cat((visual, model.state_encoder(state), encoded_language), dim=1))\n        arm, gripper, hidden = decoder(features[None], hidden)\n        return arm[0], gripper[0], hidden\n\n    def warm_context(row):\n        length=row.get(\'context_len\',0)\n        hidden=None\n        if length:\n            prefix=dict(row,context_len=0)\n            with torch.no_grad():\n                for start,stop in sequence_chunks(length,args.window):\n                    _,_,hidden=predict(prefix,start,stop,hidden)\n            hidden=hidden.detach()\n        return hidden\n\n    def objective(arm, gripper, target):\n        arm_loss = F.smooth_l1_loss((arm-target[:, :6])/label_scale, torch.zeros_like(arm))\n        grip_loss = F.binary_cross_entropy_with_logits(gripper, (target[:, 6] < 0).float(), pos_weight=pos_weight)\n        return arm_loss + .5*grip_loss\n\n    # Exercise the actual CUDA forward/backward path before the sustained run.\n    model.train(); model.vision.eval(); decoder.train()\n    arm, gripper, hidden = predict(train[0], 0, min(8, len(train[0][\'actions\'])), None)\n    target = train[0][\'actions\'][:len(arm)].to(device)\n    loss = objective(arm, gripper, target)\n    require(tuple(arm.shape) == (len(target), 6) and tuple(gripper.shape) == (len(target),), \'Forward shape mismatch\')\n    require(torch.isfinite(loss).item(), \'Nonfinite preflight loss\')\n    loss.backward()\n    require(all(p.grad is None or torch.isfinite(p.grad).all().item() for p in parameters), \'Nonfinite preflight gradients\')\n    require(model.token_embedding.weight.grad is not None and model.token_embedding.weight.grad.abs().sum().item() > 0, \'Language branch has no gradient\')\n    require(all(p.grad is None for p in model.vision.parameters()), \'Frozen vision received gradients\')\n    optimizer.zero_grad(set_to_none=True)\n    print(\'TRAINING_PREFLIGHT_PASS\', json.dumps(dict(cuda=str(device), state_dim=9, action_dim=7, language_gradient=True, vision_frozen=True)), flush=True)\n\n    protocol = dict(format=\'color_temporal_action_v1\', parent_sha256=baseline_sha, warm_start_sha256=warm_sha, manifest=str(args.manifest),\n                    manifest_sha256=file_sha(args.manifest), train_episodes=46, validation_episodes=4,\n                    validation_offset_mm=[0,10], train_samples=sum(len(r[\'actions\']) for r in train),\n                    validation_samples=sum(len(r[\'actions\']) for r in valid), epochs=args.epochs, patience=args.patience,\n                    sequence_window=args.window, recurrent_reset=\'episode start; hidden detached between training chunks\',\n                    learner_inputs=[\'table_cam\',\'wrist_cam\',\'eef_pos\',\'eef_quat\',\'gripper_pos\',\'language_tokens\'],\n                    uses_progress_input=False, uses_object_pose_input=False, vision_frozen=True,\n                    pretrained_initialization=True, visual_review=\'assistant reviewed original, recovery and diagonal and all five range20 comparison images and the additional x20_y-20 red comparison image; color/target correspondence passed; replay recovery comparison also reviewed\',\n                    checkpoint_policy=\'best validation loss among trained epochs; physical recovery requires rollout evaluation\',\n                    learning_rate=1e-5, recovery_context_steps=500, context_loss=False, context_gradients=False,\n                    limitations=\'Offline validation does not establish color selection, pick, or 3-second hold in closed-loop simulation.\')\n    atomic_json(out/\'training_protocol.json\', protocol)\n\n    def evaluate(rows):\n        model.eval(); decoder.eval()\n        total = 0; accumulated = 0.; correct = 0; mse = torch.zeros(6, device=device)\n        with torch.no_grad():\n            for row in rows:\n                hidden = warm_context(row)\n                for start, stop in sequence_chunks(len(row[\'actions\']), args.window):\n                    arm, g, hidden = predict(row, start, stop, hidden)\n                    target = row[\'actions\'][start:stop].to(device)\n                    accumulated += objective(arm, g, target).item()*(stop-start)\n                    correct += ((g >= 0) == (target[:,6] < 0)).sum().item()\n                    mse += ((arm-target[:,:6])**2).sum(dim=0)\n                    total += stop-start\n        rmse = (mse/total).sqrt().cpu().tolist()\n        return dict(loss=accumulated/total, gripper_accuracy=correct/total, arm_rmse=rmse,\n                    translation_rmse_mm=[v*.5*1000 for v in rmse[:3]], rotation_rmse_deg=[v*.5*180/math.pi for v in rmse[3:]])\n\n    def checkpoint(epoch, metrics):\n        state = dict(format=\'color_temporal_action_v1\', config=config,\n                     model={k:v.detach().cpu() for k,v in model.state_dict().items()},\n                     temporal_state={k:v.detach().cpu() for k,v in decoder.state_dict().items()},\n                     parent_sha256=baseline_sha, instructions=[\'pick up the red cube\',\'pick up the blue cube\'],\n                     action_scale=.5, step_dt=.02, quaternion_order=\'xyzw\', state_order=[\'eef_pos\',\'eef_quat\',\'gripper_pos\'],\n                     image_mean=[.485,.456,.406], image_std=[.229,.224,.225], epoch=epoch, validation=metrics,\n                     model_code_sha256=file_sha(out/\'color_model.py\'), temporal_code_sha256=file_sha(out/\'color_temporal.py\'),\n                     protocol=protocol)\n        temporary=out/\'best.pt.tmp\'\n        torch.save(state, temporary)\n        temporary.replace(out/\'best.pt\')\n\n    best=float(\'inf\'); best_epoch=0; best_metrics=None; durations=[]\n    baseline_metrics=evaluate(valid)\n    print(\'INITIAL_OFFLINE_VALIDATION\',json.dumps(baseline_metrics),flush=True)\n    with (out/\'metrics.jsonl\').open(\'w\',encoding=\'utf-8\') as logfile:\n        for epoch in range(1,args.epochs+1):\n            epoch_started=time.monotonic()\n            model.train(); model.vision.eval(); decoder.train()\n            order=train[:];random.shuffle(order)\n            training_loss=0.;count=0\n            for row in order:\n                hidden=warm_context(row)\n                for start,stop in sequence_chunks(len(row[\'actions\']),args.window):\n                    optimizer.zero_grad(set_to_none=True)\n                    arm,g,hidden=predict(row,start,stop,hidden)\n                    loss=objective(arm,g,row[\'actions\'][start:stop].to(device))\n                    require(torch.isfinite(loss).item(),\'Nonfinite training loss\')\n                    loss.backward()\n                    norm=torch.nn.utils.clip_grad_norm_(parameters,1.)\n                    require(torch.isfinite(norm).item(),\'Nonfinite gradient norm\')\n                    optimizer.step()\n                    hidden=hidden.detach()\n                    training_loss+=loss.item()*(stop-start);count+=stop-start\n            metrics=evaluate(valid)\n            improved=metrics[\'loss\']<best-1e-5\n            if improved:\n                checkpoint(epoch,metrics);best=metrics[\'loss\'];best_epoch=epoch;best_metrics=metrics\n            durations.append(time.monotonic()-epoch_started)\n            seconds_per_epoch=sum(durations[-5:])/len(durations[-5:])\n            row=dict(epoch=epoch,max_epochs=args.epochs,train_loss=training_loss/count,validation=metrics,\n                     best_epoch=best_epoch,saved_best=improved,elapsed_minutes=round((time.monotonic()-started)/60,2),\n                     maximum_remaining_minutes=round(seconds_per_epoch*(args.epochs-epoch)/60,2))\n            logfile.write(json.dumps(row)+\'\\n\');logfile.flush()\n            print(\'COLOR_TRAIN_EPOCH\',json.dumps(row),flush=True)\n            if epoch>=50 and epoch-best_epoch>=args.patience:\n                print(\'EARLY_STOP\',epoch,\'best_epoch\',best_epoch,flush=True)\n                break\n    require((out/\'best.pt\').is_file(),\'No trained checkpoint saved\')\n    saved=torch.load(out/\'best.pt\',map_location=\'cpu\',weights_only=True)\n    require(saved[\'format\']==\'color_temporal_action_v1\' and saved[\'epoch\']==best_epoch,\'Checkpoint read-back failed\')\n    require(file_sha(baseline_path)==baseline_sha,\'Baseline changed\')\n    summary=dict(completed=True,training_performed=True,best_epoch=best_epoch,epochs_run=epoch,\n                 train_episodes=46,validation_episodes=4,checkpoint=str(out/\'best.pt\'),checkpoint_sha256=file_sha(out/\'best.pt\'),\n                 best_validation=best_metrics,initial_validation=baseline_metrics,elapsed_minutes=round((time.monotonic()-started)/60,2),\n                 vision_frozen=True,uses_progress_input=False,uses_object_pose_input=False,closed_loop_evaluation_performed=False)\n    atomic_json(out/\'training_summary.json\',summary)\n    text=\'STEP5_COLOR_TRAINING_SUMMARY \'+json.dumps(summary)+\'\\n\'\n    (out/\'share_results.txt\').write_text(text)\n    print(\'\\n\'+text,flush=True)\n    print(\'SHARE_RESULTS_FILE\',out/\'share_results.txt\',flush=True)\n    print(\'TRAINED_CHECKPOINT\',out/\'best.pt\',flush=True)\n\nif __name__==\'__main__\':\n    import traceback\n    try:\n        main()\n    except Exception:\n        print(\'STEP5_COLOR_TRAINING_ERROR\\n\'+traceback.format_exc(),flush=True)\n        raise SystemExit(1)\n'

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--manifest',type=Path,required=True)
    parser.add_argument('--epochs',type=int,default=300)
    args=parser.parse_args()
    if not args.manifest.is_file():raise RuntimeError('Audited manifest missing: '+str(args.manifest))
    if args.epochs<=0:raise RuntimeError('Epochs must be positive')
    dest=Path('/workspace/step5')
    root=Path('/workspace/step4')
    needed=[root/'vla_interior_gripper29_fit_gx7ippj0/candidate.pt',args.manifest.parent/'audit_results.json']
    for path in needed:
        if not path.is_file():raise RuntimeError('Required file missing: '+str(path))
    out=Path(tempfile.mkdtemp(prefix='color_train_replay_recovery_',dir=dest))
    print('TRAINING_DIRECTORY',out,flush=True)
    (out/'color_model.py').write_text(MODEL_SOURCE,encoding='utf-8')
    (out/'color_temporal.py').write_text(TEMPORAL_SOURCE,encoding='utf-8')
    (out/'train_worker.py').write_text(WORKER_SOURCE,encoding='utf-8')
    paths=[root/'.runtime_packages',root/'python_packages',Path('/isaac-sim/extsDeprecated/omni.isaac.ml_archive/pip_prebundle'),root/'baseline_inputs/environment/runtime_packages']
    env=os.environ.copy()
    env['PYTHONDONTWRITEBYTECODE']='1'
    env['PYTHONUNBUFFERED']='1'
    env['OMP_NUM_THREADS']='8'
    env['PYTHONPATH']=os.pathsep.join([str(p) for p in paths if p.is_dir()]+[env.get('PYTHONPATH','')])
    command=[sys.executable,'-u',str(out/'train_worker.py'),'--manifest',str(args.manifest),'--output-dir',str(out),'--epochs',str(args.epochs)]
    logpath=out/'console.log'
    print('CONSOLE_LOG',logpath,flush=True)
    with logpath.open('w',encoding='utf-8') as log:
        proc=subprocess.Popen(command,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace',bufsize=1)
        try:
            for line in proc.stdout:
                print(line,end='',flush=True)
                try:log.write(line);log.flush()
                except OSError as exc:print('LOG_WRITE_FAILED',repr(exc),flush=True)
            code=proc.wait()
        finally:
            if proc.poll() is None:
                proc.terminate()
                try:proc.wait(timeout=10)
                except subprocess.TimeoutExpired:proc.kill();proc.wait()
            proc.stdout.close()
    if code or not (out/'training_summary.json').is_file():
        print('TRAINING_INCOMPLETE', 'exit_code=',code,'directory=',out,flush=True)
        raise SystemExit(code or 1)

if __name__=='__main__':main()
